(function(){
'use strict';
let dialog,client=null,progress=null,timer=null;
const owner=()=>typeof estProprietairePrincipalInterface==='function'&&estProprietairePrincipalInterface()&&cdqAccessState==='ready';
async function rpc(name,args=[]){if(!owner())throw Error('Réservé au propriétaire principal.');const email=utilisateurCourantEmail,result=await window.cdqAppelServeur(name,args);if(!owner()||email!==utilisateurCourantEmail)throw Error('Le compte a changé.');return result;}
function status(text){dialog.querySelector('[data-status]').textContent=text;}
function button(label,fn){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=async()=>{b.disabled=true;try{await fn();}catch(e){status(e.message||String(e));}finally{b.disabled=false;}};return b;}
function render(){if(!dialog)return;const p=progress;dialog.querySelector('[data-client]').textContent=client?.nom||'';const bar=dialog.querySelector('progress');if(p?.percent==null)bar.removeAttribute('value');else bar.value=p.percent;dialog.querySelector('[data-counts]').textContent=!p?.exists?'Prêt à parcourir uniquement ce dossier client et ses sous-dossiers.':p.phase==='scan'?'Inventaire : '+p.total+' Sheets trouvés…':p.processed+' / '+p.total+' vérifiés · '+p.percent+' % · '+p.converted+' PDF créés · '+p.errors+' à vérifier';status(p?.message||'');dialog.querySelector('[data-current]').textContent=p?.current||'';const ul=dialog.querySelector('ul');ul.replaceChildren();for(const issue of p?.issues||[]){const li=document.createElement('li');li.textContent=issue.file+' : '+issue.error;ul.append(li);}dialog.querySelector('details').hidden=!p?.errors;}
async function poll(){if(!owner()||!dialog?.open||!client)return;try{progress=await rpc('obtenirConversionPlancherCDQV2525',[client.id]);render();}catch(e){status(e.message);}finally{clearTimeout(timer);if(dialog?.open)timer=setTimeout(poll,10000);}}
async function open(){
 if(!owner())return;if(!compagnieSelectionnee){afficherErreur(Error('Ouvrez le client source avant de convertir ses Sheets.'));return;}
 client={id:String(compagnieSelectionnee),nom:nomCompagnieSelectionnee||''};
 if(!dialog){dialog=document.createElement('dialog');dialog.id='cdqMigration25';dialog.setAttribute('aria-label','Conversion des Sheets de plancher');dialog.innerHTML='<h2>Sheets → PDF de plancher</h2><h3 data-client></h3><p>Source : ce client et ses sous-dossiers. Destination : VAPP1.0 → même client → Rapports d’étalonnage. Les Sheets originaux restent conservés; les PDF gardent leur titre.</p><progress max="100"></progress><p data-counts></p><p data-current></p><p data-status role="status"></p><details><summary>Fichiers à vérifier</summary><ul></ul></details><p>La conversion continue sur le serveur même si CDQ ou le téléphone est fermé. Un fichier est traité à la fois, environ chaque minute. « Charge utilisée » du Sheet devient « Charge de contrainte » du PDF.</p><footer></footer>';
  const footer=dialog.querySelector('footer');for(const [label,retry] of [['Démarrer / reprendre',false],['Réessayer les erreurs',true]])footer.append(button(label,async()=>{progress=await rpc('demarrerConversionPlancherCDQV2525',[client.id,retry]);render();}));footer.append(button('Pause',async()=>{progress=await rpc('suspendreConversionPlancherCDQV2525',[client.id]);render();}),button('Fermer',()=>dialog.close()));dialog.onclose=()=>clearTimeout(timer);document.body.append(dialog);
 }
 if(!dialog.open)dialog.showModal();await poll();
}
function mount(){for(const target of document.querySelectorAll('#pc18Users,#cdqAdminSettingsButton')){const parent=target.parentElement;let b=parent.querySelector('[data-migration25]');if(owner()&&!b){b=button('Convertir les Sheets de plancher',open);b.dataset.migration25='';b.className=target.className;parent.append(b);}if(b)b.hidden=!owner();}if(!owner()&&dialog?.open)dialog.close();}
let scheduled=false;new MutationObserver(()=>{if(!scheduled){scheduled=true;requestAnimationFrame(()=>{scheduled=false;mount();});}}).observe(document.body,{childList:true,subtree:true});window.addEventListener('cdq:access-ready',mount);window.cdqFloorMigration25={open};mount();
})();
